function validasiData(rows) {
  const errors = [];
  const idTerlihat = new Set();

  rows.forEach((row, index) => {
    const posisi = `baris ke-${index + 1} (id=${row.id})`;

    if (idTerlihat.has(row.id)) errors.push(`${posisi}: id duplikat`);
    idTerlihat.add(row.id);

    if (row.id !== index + 1) {
      errors.push(`${posisi}: id tidak urut, seharusnya ${index + 1}`);
    }
    if (row.juz < 1 || row.juz > 30) errors.push(`${posisi}: juz di luar range 1-30`);
    if (row.hari_dalam_juz < 1 || row.hari_dalam_juz > 6) {
      errors.push(`${posisi}: hari_dalam_juz di luar range 1-6`);
    }
    if (row.hari_global < 1 || row.hari_global > 180) {
      errors.push(`${posisi}: hari_global di luar range 1-180`);
    }
    const waktuValid = ['subuh', 'dzuhur', 'ashar', 'maghrib', 'isya'];
    if (!waktuValid.includes(row.waktu_sholat)) {
      errors.push(`${posisi}: waktu_sholat "${row.waktu_sholat}" tidak valid`);
    }
    if (!row.surat_ayat) errors.push(`${posisi}: surat_ayat kosong`);
  });

  return errors;
}

console.log(`Mulai seeding ${data.length} baris bacaan...`);

const errors = validasiData(data);
if (errors.length > 0) {
  console.log(`\n❌ Ditemukan ${errors.length} masalah, seeding DIBATALKAN:\n`);
  errors.forEach((e) => console.log(`  - ${e}`));
  process.exit(1);
}

data.forEach((row) => {
  const paddedId = String(row.id).padStart(4, '0');
  insertBacaan({
    ...row,
    path_arab: `images/arab_${paddedId}.jpg`,
    path_indo: `images/indo_${paddedId}.jpg`,
  });
});

const total = countBacaan();
console.log(`\n✅ Selesai. Total baris di tabel bacaan sekarang: ${total}`);

if (total < 900) {
  console.log(`⚠️  Masih kurang ${900 - total} baris lagi sampai lengkap 900.`);
} else if (total === 900) {
  console.log('🎉 Lengkap 900 baris!');
} else {
  console.log(`⚠️  Lebih dari 900 (${total})? Cek kemungkinan data lama belum dihapus / dobel insert.`);
}